begin;
do $test$
declare uid uuid:=extensions.gen_random_uuid();peer uuid:=extensions.gen_random_uuid();sid uuid:=extensions.gen_random_uuid();psid uuid:=extensions.gen_random_uuid();eid uuid:=extensions.gen_random_uuid();actor jsonb;peer_actor jsonb;result jsonb;nid uuid;native_key text;lease uuid;next_page jsonb;i integer;
begin
 if to_regclass('private.admin_security_notices')is null then raise exception 'Private notice foundation missing';end if;
 if has_function_privilege('authenticated','public.enqueue_admin_security_notice(uuid)','execute')or has_function_privilege('anon','public.query_own_admin_notices(jsonb,integer,integer)','execute')then raise exception 'Browser RPC access widened';end if;
 insert into auth.users(id,email,email_confirmed_at)values(uid,'notice-owner@local.invalid',now()),(peer,'notice-peer@local.invalid',now());
 insert into public.admin_profiles(user_id,admin_code,display_name,is_active,status)values(uid,'JN-ADM-209981','Notice Owner',true,'active'),(peer,'JN-ADM-209982','Notice Peer',true,'active');
 insert into public.rbac_user_platform_roles(user_id,role_id,scope)select u,id,'admin'from public.rbac_platform_roles cross join unnest(array[uid,peer])u where code='super_admin'and scope='admin';
 insert into auth.sessions(id,user_id,aal,created_at,updated_at)values(sid,uid,'aal1',now(),now()),(psid,peer,'aal1',now(),now());
 update public.security_settings set admin_totp_enforced=false;
 actor:=jsonb_build_object('userId',uid,'sessionId',sid,'roleVersion',(select version from public.rbac_user_claim_versions where user_id=uid),'currentLevel','aal1');
 peer_actor:=jsonb_build_object('userId',peer,'sessionId',psid,'roleVersion',(select version from public.rbac_user_claim_versions where user_id=peer),'currentLevel','aal1');
 native_key:='native_auth:'||eid;
 perform private.admin_activity_append(jsonb_build_object('id',eid,'source','native_auth','sourceId',eid,'actorUserId',uid,'targetUserId',null,'action','auth.user_updated_password','outcome','succeeded','occurredAt',clock_timestamp(),'context',null,'provenance','Disposable native receipt'),false);
 result:=public.enqueue_admin_security_notice(eid);
 if(result->>'created')::integer<>2 then raise exception 'Eligible recipient notices missing';end if;
 if(public.enqueue_admin_security_notice(eid)->>'created')::integer<>0 then raise exception 'Notice replay duplicated';end if;
 result:=public.query_own_admin_notices(actor,1,1000);
 if(result->>'totalItems')::integer<>1 or(result->>'pageSize')::integer<>100 then raise exception 'Own inbox bounds incorrect';end if;
 select id into nid from private.admin_security_notices where recipient_user_id=peer and event_key=native_key;
 perform public.own_admin_email_preferences(peer_actor,'{"admin_security_email_opt_in":true,"admin_recommendation_email_opt_in":false}');
 update private.admin_notification_controls set delivery_enabled=true,delivery_cutover=clock_timestamp()-interval '1 minute'where singleton;
 perform public.queue_admin_notice_email(nid,jsonb_build_object('from','JnUITS <no-reply@jnuits.org.bd>','replyTo','no-reply@jnuits.org.bd','to','notice-peer@local.invalid','subject','Fixture peer notice','html','<p>Fixture</p>','text','Fixture'));
 if public.query_own_admin_notices(peer_actor,1,25)#>>'{items,0,deliveryStatus}'is distinct from 'pending'then raise exception 'Own inbox lacks safe delivery status';end if;
 update private.admin_notification_controls set delivery_enabled=false,delivery_cutover=null where singleton;
 if public.mark_own_admin_notice_read(actor,nid)then raise exception 'Cross-recipient mark succeeded';end if;
 if not public.mark_own_admin_notice_read(peer_actor,nid)then raise exception 'Owned mark failed';end if;
 if public.query_own_admin_notices(peer_actor,1,25)->>'unreadCount'<>'0'then raise exception 'Unread state stale';end if;
 result:=public.own_admin_email_preferences(actor,null);
 if result->>'admin_security_email_opt_in'<>'false'or result->>'admin_recommendation_email_opt_in'<>'false'then raise exception 'New optional email default is on';end if;
 result:=public.own_admin_email_preferences(actor,'{"admin_security_email_opt_in":true,"admin_recommendation_email_opt_in":false}');
 if result->>'admin_security_email_opt_in'<>'true'then raise exception 'Self opt-in did not persist';end if;
 begin perform public.own_admin_email_preferences(actor,'{"admin_security_email_opt_in":true,"admin_recommendation_email_opt_in":false,"userId":"other"}');raise exception 'Arbitrary recipient accepted';exception when invalid_parameter_value then null;end;
 -- Details may expire; durable source/recipient receipts must still prevent replay.
 delete from private.admin_security_notices where event_key=native_key;
 if(public.enqueue_admin_security_notice(eid)->>'created')::integer<>0 then raise exception 'Deleted details resurrected notices';end if;
 update public.admin_profiles set is_active=false where user_id=peer;
 begin perform public.query_own_admin_notices(peer_actor,1,25);raise exception 'Inactive recipient retained inbox access';exception when insufficient_privilege then null;end;
 -- Failed and pre-activation changes stay audit-visible without broadcasts.
 eid:=extensions.gen_random_uuid();
 perform private.admin_activity_append(jsonb_build_object('id',eid,'source','native_auth','sourceId',eid,'actorUserId',uid,'targetUserId',null,'action','auth.user_updated_password','outcome','failed','occurredAt',clock_timestamp(),'context',null,'provenance','Disposable failure'),false);
 if(public.enqueue_admin_security_notice(eid)->>'created')::integer<>0 then raise exception 'Failed change broadcast';end if;
 eid:=extensions.gen_random_uuid();
 perform private.admin_activity_append(jsonb_build_object('id',eid,'source','native_auth','sourceId',eid,'actorUserId',uid,'targetUserId',null,'action','auth.user_updated_password','outcome','succeeded','occurredAt',clock_timestamp()-interval '1 day','context',null,'provenance','Disposable backfill'),false);
 if(public.enqueue_admin_security_notice(eid)->>'created')::integer<>0 then raise exception 'Historical flood';end if;
 if(select delivery_enabled from private.admin_notification_controls where singleton)then raise exception 'Email activated before acceptance';end if;
 begin perform public.collect_admin_security_notices(500,false,extensions.gen_random_uuid());raise exception 'Unleased collection accepted';exception when insufficient_privilege then null;end;
 lease:=(public.claim_admin_accountability_job()->>'leaseId')::uuid;
 result:=public.collect_admin_security_notices(500,true,lease);
 if(result->>'created')::integer<>0 then raise exception 'Dry run creates notices';end if;
 perform public.collect_admin_security_notices(500,false,lease);
 if(public.collect_admin_security_notices(500,false,lease)->>'read')::integer<>0 then raise exception 'Processed event cursor did not advance';end if;
 perform public.release_admin_accountability_job(lease,false);
 if public.get_admin_recommendation_inputs(uid,true)is not null then raise exception 'Opt-out recommendations generated';end if;
 perform public.own_admin_email_preferences(actor,'{"admin_security_email_opt_in":true,"admin_recommendation_email_opt_in":true}');
 insert into public.content_posts(content_type,slug,title,status)values('blog','notice-fixture-'||uid,'Disposable pending blog','pending_review');
 result:=public.get_admin_recommendation_inputs(uid,true);
 if result->>'enrollment'<>'needs_setup'or result->'admin'->>'display_name'<>'Notice Owner'then raise exception 'Authoritative recommendation inputs missing';end if;
 if result?'sessionId'or result?'currentLevel'then raise exception 'Scheduled inputs invented a browser session';end if;
 if not exists(select 1 from jsonb_array_elements(result->'queues')q where q->>'key'='blogs'and(q->>'count')::integer>0)then raise exception 'Recommendation queue does not match real pending blog state';end if;
 if public.get_admin_recommendation_inputs(peer,false)is not null then raise exception 'Inactive subject retained recommendations';end if;
 for i in 1..36 loop
  eid:=extensions.gen_random_uuid();
  perform private.admin_activity_append(jsonb_build_object('id',eid,'source','native_auth','sourceId',eid,'actorUserId',uid,'targetUserId',null,'action','auth.user_updated_password','outcome','succeeded','occurredAt',clock_timestamp(),'context',null,'provenance','Disposable pagination receipt'),false);
  perform public.enqueue_admin_security_notice(eid);
 end loop;
 result:=public.query_own_admin_notices(actor,1,25);next_page:=public.query_own_admin_notices(actor,2,25);
 if result->>'totalItems'<>'36'or jsonb_array_length(result->'items')<>25 or jsonb_array_length(next_page->'items')<>11 then raise exception 'Notice pagination count or page bounds incorrect';end if;
 if exists(select 1 from jsonb_array_elements(result->'items')a join jsonb_array_elements(next_page->'items')b on a->>'id'=b->>'id')then raise exception 'Notice pages overlap';end if;
 if public.query_own_admin_notices(actor,999,25)->>'page'<>'2'then raise exception 'Notice out-of-range page not clamped';end if;
end $test$;
rollback;
